parameters.jsCode:
// Validates the contract BEFORE touching the database (S-E). A mis-mapped field has to
// blow up here: if it blows up after the key is claimed, the patient is burned forever
// by INV-1 and can only be recovered by deleting the row by hand.
const e = $input.first().json ?? {};

const key      = String(e.unique_key ?? '').trim();
const template = String(e.template   ?? '').trim();
const phone    = String(e.phone      ?? '').trim();

if (!key)      throw new Error('Broken contract: empty unique_key');
if (!template) throw new Error(`Broken contract: empty template (key ${key})`);

// E.164: '+' and 8 to 15 digits. If it does not look like one, we do not guess (spec 4.5).
if (!/^\+[1-9]\d{7,14}$/.test(phone)) {
  throw new Error(`Phone is not E.164: "${phone}" (key ${key})`);
}

const params = Array.isArray(e.params) ? e.params : [];

const request_body = {
  from: '+15555550199',            // the clinic's business number, confirmed 2026-09-05 (task 1.5)
  to: phone,
  type: 'template',
  externalId: key,                 // comes back inside the delivery webhook (INV-5, spec 8)
  template: {
    name: template,
    language: { code: 'es', policy: 'deterministic' },  // all three templates are 'es' (task 1.1)
    components: params.length
      ? [{ type: 'body', parameters: params.map((v) => ({ type: 'text', text: String(v) })) }]
      : [],
  },
};

// The input is returned too, so the next node's INSERT can read it from $json.
return [{ json: { ...e, request_body } }];

// A 2xx is NOT enough to write 'sent' (S-D). sendDirectly can answer 200
// with status 'failed': the message was rejected and the 2xx only means "I understood you".
const r = $input.first().json ?? {};
const failed = (r.status ?? '') === 'failed';

return [{ json: {
  status:        failed ? 'failed' : 'sent',
  wamid:         String(r.wamid ?? ''),          // the wamid, and only the wamid
  ycloud_id:     String(r.id ?? ''),             // YCloud's own id: GET /v2/whatsapp/messages/{id}
  error_code:    failed ? String(r.errorCode ?? 'NO_CODE') : '',
  error_message: failed ? String(r.errorMessage ?? 'no detail').slice(0, 500) : '',
}}];

// The question is not "did it fail?" but "did someone CLAIM it did not go out?" (S-D).
//   4xx     -> explicit, deliberate rejection -> 'failed'
//   5xx     -> the intermediary does not know -> 'ambiguous'
//   nothing -> timeout, DNS, dropped link    -> 'ambiguous'
// Never retried from here: that would be INV-4 in reverse.
const e = $input.first().json ?? {};
const err = e.error ?? e;

// The shape of the error item changes between versions: read it defensively.
const raw = err.httpCode ?? err.statusCode ?? err.status ?? err.code ?? null;
const code = Number(raw);
const isRejection = Number.isFinite(code) && code >= 400 && code <= 499;

const detail = err.description ?? err.message ?? e.message ?? 'no detail';

return [{ json: {
  status:        isRejection ? 'failed' : 'ambiguous',
  wamid:         '',
  ycloud_id:     '',
  error_code:    String(raw ?? 'NO_RESPONSE'),
  error_message: String(detail).slice(0, 500),
}}];

const r = $input.first().json ?? {};
const e = $('Input').item.json;
const status = r.status ?? '';

const when = DateTime.now().setZone('America/Costa_Rica').toFormat('dd/MM/yyyy HH:mm');

// No asterisks or underscores: the Telegram node was meant to run without parse_mode (INV-15),
// and keys carry underscores that would break an unbalanced Markdown.
const whatToDo = status === 'ambiguous'
  ? 'Do NOT resend. The delivery webhook may close it on its own. If it is still like this when the 12 h expire, a human decides.'
  : status === 'failed'
    ? 'Do NOT resend. The key is already written and blocks the retry. To contact the patient again, the row has to be deleted by hand.'
    : 'The UPDATE touched no rows: someone else moved the record, or the row is missing. Check the row in bot.sends.';

const text =
  `SEND NOT CONFIRMED - ${status || 'no record'}\n\n` +
  `When: ${when}\n` +
  `Patient: ${e.last_name} (milestone ${e.milestone})\n` +
  `Key: ${e.unique_key}\n` +
  (r.error_code    ? `Code: ${r.error_code}\n`      : '') +
  (r.error_message ? `Detail: ${r.error_message}\n` : '') +
  `\n${whatToDo}`;

return [{ json: { status, text } }];
